(7134017, 1091727, 40391, '<td valign="top">Congrats Doc. Very deserved ribbon.</td>', 'Congrats Doc. Very deserved ribbon.', '2013-11-23 15:16:21.000000', NULL, 0),
(7134030, 1091727, 114969, '<td valign="top">Using the bright orange vase on the left side was an extremely clever idea: it really creates a very efficient and dynamic line with the recursive effect. Very well done, congratulations on your ribbon.</td>', 'Using the bright orange vase on the left side was an extremely clever idea: it really creates a very efficient and dynamic line with the recursive effect. Very well done, congratulations on your ribbon.', '2013-11-23 16:50:26.000000', NULL, 0),
(7134032, 1092107, 114969, '<td valign="top">It really reminds Escher work, wonderful process. Congratulations on your nice finish! :)</td>', 'It really reminds Escher work, wonderful process. Congratulations on your nice finish! :)', '2013-11-23 16:51:55.000000', NULL, 0),
(7134033, 1092192, 114969, '<td valign="top">You got me there Mary Ann, I was convinced this was Wendy''s entry. Great work! I love the tones, the bright orange works like a charm on this rich brown background, when put in the perspective of the repeat images. Congratulations on your great finish :)</td>', 'You got me there Mary Ann, I was convinced this was Wendy''s entry. Great work! I love the tones, the bright orange works like a charm on this rich brown background, when put in the perspective of the repeat images. Congratulations on your great finish :)', '2013-11-23 16:57:43.000000', NULL, 0),
(7134034, 1092165, 14476, '<td valign="top">Fun shot, Brennan.  Congratulations on the ribbon.</td>', 'Fun shot, Brennan.  Congratulations on the ribbon.', '2013-11-23 16:57:58.000000', NULL, 0),
(7134035, 1092050, 114969, '<td valign="top">You already know I love your entry Pam, it is extremely creative and smart to make the different levels of depth interact. Great imagination! Congratulations on your nice finish :)</td>', 'You already know I love your entry Pam, it is extremely creative and smart to make the different levels of depth interact. Great imagination! Congratulations on your nice finish :)', '2013-11-23 16:58:59.000000', NULL, 0),
(7134036, 1091919, 114969, '<td valign="top">Yes! What a fantastic entry Alessandro. My favorite of the challenge, hands down. I love how everything is perfectly organized: the wand and the eyes point perfectly to the repeated pictures, which are also underlined by the hand, the magician theme is a very clever choice given the challenge topic, the curvy red curtains work great with the main spiral... Great, great work. Hats off! ;-)</td>', 'Yes! What a fantastic entry Alessandro. My favorite of the challenge, hands down. I love how everything is perfectly organized: the wand and the eyes point perfectly to the repeated pictures, which are also underlined by the hand, the magician theme is a very clever choice given the challenge topic, the curvy red curtains work great with the main spiral... Great, great work. Hats off! ;-)', '2013-11-23 17:07:22.000000', NULL, 0),
(7134037, 1092019, 114969, '<td valign="top">As often with your entries, it is hard to not smile like a child when looking at it :) Thanks for your refreshing take on that challenge.</td>', 'As often with your entries, it is hard to not smile like a child when looking at it :) Thanks for your refreshing take on that challenge.', '2013-11-23 17:09:39.000000', NULL, 0),
(7134042, 1092101, 114969, '<td valign="top">I love that one Wendy, the idea is great and perfectly fits the challenge. Just a little tip for the next time you want to use that effect: according to your notes, you pasted the "magazine into the magazine" just once at a time, which of course works, but is painfully slow ;) If you do it a first time, from there instead of doing it directly a second time, you can copy the *whole* resulting picture again, and paste that inside. This way, the first time, well, you copy just one magazine, but the second time you add 2 other magazines inside, then the third time you add 4 others magazines inside, and so on. Doing this five times would give you 2^0+2^1+2^2+2^3+2^4 = 31 magazines inside the big one, probably more than enough. Anyway, congratulations on your fine work, I really enjoyed it!</td>', 'I love that one Wendy, the idea is great and perfectly fits the challenge. Just a little tip for the next time you want to use that effect: according to your notes, you pasted the "magazine into the magazine" just once at a time, which of course works, but is painfully slow ;) If you do it a first time, from there instead of doing it directly a second time, you can copy the *whole* resulting picture again, and paste that inside. This way, the first time, well, you copy just one magazine, but the second time you add 2 other magazines inside, then the third time you add 4 others magazines inside, and so on. Doing this five times would give you 2^0+2^1+2^2+2^3+2^4 = 31 magazines inside the big one, probably more than enough. Anyway, congratulations on your fine work, I really enjoyed it!', '2013-11-23 17:23:23.000000', NULL, 0),
(7134047, 1091727, 28742, '<td valign="top">Congrats! Nice job, Chuck!</td>', 'Congrats! Nice job, Chuck!', '2013-11-23 17:29:31.000000', NULL, 0),
(7134048, 1092052, 28742, '<td valign="top">Well done! I like the corner angle - unique.</td>', 'Well done! I like the corner angle - unique.', '2013-11-23 17:31:44.000000', NULL, 0),
