(7134610, 1091727, 52549, '<td valign="top">So pleased this beauty ribboned for you. Congrats.</td>', 'So pleased this beauty ribboned for you. Congrats.', '2013-11-25 05:26:45.000000', NULL, 0),
(7134703, 1092165, 112136, '<td valign="top">brilliant!</td>', 'brilliant!', '2013-11-25 10:31:36.000000', NULL, 0),
